# 사용법:  bash agents/harness/evals/checks.sh   (또는 pnpm check)
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
cd "$ROOT"

FAIL=0
run() {
  local name="$1"; shift
  echo ""
  echo "▶ $name"
  echo "  \$ $*"
  if "$@"; then
    echo "  ✅ PASS — $name"
  else
    echo "  ❌ FAIL — $name"
    FAIL=1
  fi
}

echo "════════════════════════════════════════"
